//! Finite, generated-input comparison of fragment encoding before/after direct mdat.
//!
//! cargo run --release -p sapflow-hls --example fmp4-encode-bench -- \
//!   --iterations 2000 --rounds 6
//!
//! Inputs model compressed payload sizes only; they are generated byte patterns,
//! not decodable video/audio, codec performance or media-quality evidence.
//! Run alone on the chosen benchmark machine and retain its source/binary hashes.

use bytes::Bytes;
use sapflow_hls::fmp4::{self, AUDIO_TRACK, Sample, TrackRun, VIDEO_TRACK};
use std::{error::Error, hint::black_box, time::Instant};

#[path = "support/fmp4_reference.rs"]
mod reference;

#[derive(Clone, Copy)]
enum Writer {
    Reference,
    Candidate,
}

impl Writer {
    fn name(self) -> &'static str {
        match self {
            Self::Reference => "reference",
            Self::Candidate => "candidate",
        }
    }

    fn encode(self, sequence: u32, runs: &[TrackRun<'_>]) -> Bytes {
        match self {
            Self::Reference => reference::before_direct_mdat(sequence, runs, false, None),
            Self::Candidate => fmp4::encode_part(sequence, runs),
        }
    }
}

struct Workload {
    name: &'static str,
    video: Vec<Sample>,
    audio: Vec<Sample>,
}

impl Workload {
    fn audio_only(name: &'static str, frames: usize, payload_bytes: usize) -> Self {
        Self {
            name,
            video: Vec::new(),
            audio: (0..frames)
                .map(|i| Sample {
                    duration: 1024,
                    cts: 0,
                    sync: true,
                    data: Bytes::from(vec![0x70 + i as u8; payload_bytes]),
                })
                .collect(),
        }
    }

    fn new(name: &'static str, first_video: usize, other_video: usize) -> Self {
        Self {
            video: (0..6)
                .map(|i| Sample {
                    duration: 3000,
                    cts: 0,
                    sync: i == 0,
                    data: Bytes::from(vec![
                        0x40 + i as u8;
                        if i == 0 { first_video } else { other_video }
                    ]),
                })
                .collect(),
            ..Self::audio_only(name, 10, 320)
        }
    }

    fn runs(&self) -> Vec<TrackRun<'_>> {
        let mut runs = Vec::with_capacity(2);
        if !self.video.is_empty() {
            runs.push(TrackRun {
                track_id: VIDEO_TRACK,
                base_time: 900_000,
                samples: &self.video,
            });
        }
        if !self.audio.is_empty() {
            runs.push(TrackRun {
                track_id: AUDIO_TRACK,
                base_time: 480_000,
                samples: &self.audio,
            });
        }
        runs
    }
}

fn checksum(bytes: &[u8]) -> u64 {
    bytes.iter().fold(0xcbf29ce484222325, |hash, byte| {
        (hash ^ u64::from(*byte)).wrapping_mul(0x100000001b3)
    })
}

fn measure(writer: Writer, workload: &Workload, iterations: u32, round: u32, position: usize) {
    let runs = workload.runs();
    let expected = Writer::Reference.encode(iterations - 1, &runs);
    let expected_bytes = expected.len() as u64 * u64::from(iterations);
    let mut last = Bytes::new();
    let mut output_bytes = 0u64;
    let started = Instant::now();
    for sequence in 0..iterations {
        let encoded = writer.encode(black_box(sequence), black_box(&runs));
        output_bytes += encoded.len() as u64;
        if sequence + 1 == iterations {
            last = black_box(encoded);
        } else {
            drop(black_box(encoded));
        }
    }
    let elapsed = started.elapsed();
    assert_eq!(output_bytes, expected_bytes, "encoded byte count");
    assert_eq!(last, expected, "complete final fragment byte equality");
    println!(
        "{{\"workload\":\"{}\",\"round\":{},\"position\":{},\"variant\":\"{}\",\"iterations\":{},\"elapsed_ns\":{},\"ns_per_part\":{:.3},\"output_bytes\":{},\"last_fnv1a64\":\"{:016x}\"}}",
        workload.name,
        round,
        position,
        writer.name(),
        iterations,
        elapsed.as_nanos(),
        elapsed.as_secs_f64() * 1_000_000_000.0 / f64::from(iterations),
        output_bytes,
        checksum(&last),
    );
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut iterations = 2000u32;
    let mut rounds = 6u32;
    let mut args = std::env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--iterations" => iterations = args.next().ok_or("missing iterations")?.parse()?,
            "--rounds" => rounds = args.next().ok_or("missing rounds")?.parse()?,
            "--help" => {
                println!("fmp4-encode-bench [--iterations 2000] [--rounds 6]");
                return Ok(());
            }
            _ => return Err(format!("unknown argument: {arg}").into()),
        }
    }
    if !(1..=1_000_000).contains(&iterations) || !(1..=100).contains(&rounds) {
        return Err("iterations must be 1..1000000; rounds must be 1..100".into());
    }
    let workloads = [
        Workload::new("mixed-720p-payload-sizes", 20_000, 8500),
        Workload::new("large-idr-payload-sizes", 512 * 1024, 32 * 1024),
        Workload::audio_only("audio-only-small-payload-sizes", 10, 320),
        Workload::audio_only("single-small-audio-payload-size", 1, 32),
    ];
    // All generated sample allocation and warm-up happen outside timed batches.
    for workload in &workloads {
        let runs = workload.runs();
        for sequence in 0..16 {
            assert_eq!(
                Writer::Reference.encode(sequence, &runs),
                Writer::Candidate.encode(sequence, &runs),
                "warm-up byte equality"
            );
        }
    }
    println!(
        "{{\"kind\":\"method\",\"synthetic_payloads\":true,\"architecture\":\"{}\",\"debug_assertions\":{},\"iterations\":{},\"rounds\":{},\"timing\":\"encoding, allocation and drop; excludes fixture generation, checksum and equality checks\"}}",
        std::env::consts::ARCH,
        cfg!(debug_assertions),
        iterations,
        rounds,
    );
    for round in 1..=rounds {
        let order = if round % 2 == 1 {
            [Writer::Reference, Writer::Candidate]
        } else {
            [Writer::Candidate, Writer::Reference]
        };
        for workload in &workloads {
            for (position, writer) in order.into_iter().enumerate() {
                measure(writer, workload, iterations, round, position + 1);
            }
        }
    }
    Ok(())
}
